#include "symbol_table.h"
void milena_symbols_init(MilenaSymbolTable*t){if(t)memset(t,0,sizeof(*t));}
void milena_symbols_release(MilenaSymbolTable*t){if(!t)return;for(size_t i=0;i<t->count;i++)free(t->items[i].name);free(t->items);milena_symbols_init(t);}
void milena_symbols_enter_scope(MilenaSymbolTable*t){if(t)t->scope++;}
void milena_symbols_leave_scope(MilenaSymbolTable*t){if(!t||t->scope==0)return;while(t->count&&t->items[t->count-1].scope==t->scope){free(t->items[--t->count].name); }t->scope--;}
bool milena_symbols_exists(const MilenaSymbolTable*t,const char*n){if(!t||!n)return false;for(size_t i=t->count;i>0;i--)if(strcmp(t->items[i-1].name,n)==0)return true;return false;}
MilenaStatus milena_symbols_declare(MilenaSymbolTable*t,const char*n,MilenaError*e){if(!t||!n||!*n){milena_error_set(e,MILENA_ERR_ARGUMENT,0,0,0,"Nombre de variable inválido");return MILENA_ERR_ARGUMENT;}for(size_t i=t->count;i>0&&t->items[i-1].scope==t->scope;i--)if(strcmp(t->items[i-1].name,n)==0){milena_error_set(e,MILENA_ERR_DATA,0,0,0,"La variable ya fue declarada en este ámbito");return MILENA_ERR_DATA;}if(t->count==t->capacity){size_t c=t->capacity?t->capacity*2:8;MilenaSymbol*x=realloc(t->items,c*sizeof(*x));if(!x){milena_error_set(e,MILENA_ERR_MEMORY,0,0,0,"Sin memoria para tabla semántica");return MILENA_ERR_MEMORY;}t->items=x;t->capacity=c;}size_t index=t->count++;t->items[index].name=milena_strdup(n);if(!t->items[index].name){t->count--;milena_error_set(e,MILENA_ERR_MEMORY,0,0,0,"Sin memoria para nombre");return MILENA_ERR_MEMORY;}t->items[index].scope=t->scope;return MILENA_OK;}
